import{_ as i,C as a,c as l,o as c,a9 as r,G as o}from"./chunks/framework.DuenUNqn.js";const n="/assets/installation-1.nEs3CMDn.png",p="/assets/installation-2.wKFrthqH.png",m="/assets/installation-3.B1zxVk-e.png",u="/assets/installation-4.ByVux-_M.png",d="/assets/installation-5.ppTLOQ7A.png",k="/assets/installation-6.Cup_iIue.png",h="/assets/installation-7.BMpcuQs6.png",g="/assets/installation-8.DlrPhyCc.png",f="/assets/installation-9.OS-_ReVN.png",v=JSON.parse('{"title":"安装","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"LuckPerms","link":"/wiki/LuckPerms"},{"title":"安装","link":"/wiki/LuckPerms/install-on-a-single-server"}]},"headers":[],"relativePath":"wiki/LuckPerms/install-on-a-single-server.md","filePath":"wiki/LuckPerms/install-on-a-single-server.md"}'),P={name:"wiki/LuckPerms/install-on-a-single-server.md"};function b(_,e,L,q,y,S){const t=a("NolebaseGitContributors"),s=a("NolebaseGitChangelog");return c(),l("div",null,[e[0]||(e[0]=r('<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><h2 id="第一步-下载-luckperms-的-jar-文件" tabindex="-1">第一步：下载 LuckPerms 的 jar 文件 <a class="header-anchor" href="#第一步-下载-luckperms-的-jar-文件" aria-label="Permalink to &quot;第一步：下载 LuckPerms 的 jar 文件&quot;">​</a></h2><p>你需要做的第一件事就是下载 LuckPerms。你可以在我们的<a href="https://luckperms.net/download" target="_blank" rel="noreferrer">下载页</a>找到为各种平台准备的最新版 LuckPerms。</p><p>只需点击下载按钮，将文件保存在适当的位置即可。</p><ul><li>若你正在运行的是 Minecraft JE 版的<em>非模组</em>服，我们推荐你使用 <a href="https://papermc.io/" target="_blank" rel="noreferrer">Paper</a> 核心。</li><li>若你正在运行的是 Minecraft JE 版的<em>模组</em>服，我们推荐你使用 <a href="https://fabricmc.net/" target="_blank" rel="noreferrer">Fabric</a> 或 <a href="https://neoforged.net/" target="_blank" rel="noreferrer">NeoForge</a> 核心。</li><li>若你正在运行的是 Minecraft BE 版的服务器，我们推荐你使用 <a href="https://cloudburstmc.org/" target="_blank" rel="noreferrer">Nukkit</a> 核心。</li><li>若你正在运行的是群组服，我们推荐你使用 <a href="https://velocitypowered.com/" target="_blank" rel="noreferrer">Velocity</a> 或 <a href="https://papermc.io/downloads#Waterfall" target="_blank" rel="noreferrer">Waterfall</a>（BungeeCord）或 Velocity 核心。</li><li>若你正在运行的是 Hytale——很抱歉你（至少是现在的）选择不多！不过原版服务器已经足够使用了！</li></ul><p>如果你还没有地方托管你的服务器，来看看我们的合作伙伴 <a href="https://bisecthosting.com/luck" target="_blank" rel="noreferrer">BisectHosting</a> 吧，这家提供商会为 LuckPerms 的用户在托管游戏服务器的套餐中提供 25% 的折扣。</p><h2 id="第二步-将-luckperms-的-jar-文件放入服务器的-plugins-或-mods-文件夹下" tabindex="-1">第二步：将 LuckPerms 的 jar 文件放入服务器的 <code>plugins</code> 或 <code>mods</code> 文件夹下 <a class="header-anchor" href="#第二步-将-luckperms-的-jar-文件放入服务器的-plugins-或-mods-文件夹下" aria-label="Permalink to &quot;第二步：将 LuckPerms 的 jar 文件放入服务器的 `plugins` 或 `mods` 文件夹下&quot;">​</a></h2><p>接下来，我们需要将 LuckPerms 安装至服务器。在此之前请先确认你安装了对应的服务器核心，且已至少成功启动过一次（这是为了确保对应的文件夹能正确出现）。</p><p>找到控制面板的“文件管理器”，并打开 <code>plugins</code> 文件夹（Bukkit 和 Paper 系服务端等）或 <code>mods</code> 文件夹（Forge、Fabric、Sponge 或 Hytale 服务端等）</p><p><img src="'+n+'" alt=""><br> 在你进入 plugins 或 mods 文件夹后，点击“上传”按钮，等待界面出现后选择你在第一步下载的 LuckPerms jar 文件。最后点击“上传”。</p><p><img src="'+p+'" alt=""><br> 若你先前已经安装了旧版本的 LuckPerms，请先删除旧版本的 jar 文件。</p><h2 id="第三步-完全重启你的服务器" tabindex="-1">第三步：完全重启你的服务器 <a class="header-anchor" href="#第三步-完全重启你的服务器" aria-label="Permalink to &quot;第三步：完全重启你的服务器&quot;">​</a></h2><p>返回你的服务器控制台并通过点击“重启”按钮或输入 <code>stop</code> 等方式重新启动服务器。</p><figure><img src="'+m+'" alt="" tabindex="0"><figcaption></figcaption></figure><p>在服务器开始备份的时候，LuckPerms 会启用并创建默认的配置文件。你可以通过检查控制台来确保 LuckPerms 正常启用。</p><figure><img src="'+u+'" alt="" tabindex="0"><figcaption></figcaption></figure><p>现在，LuckPerms 已被安装并在你的服务器上启用了！你可以接着阅读本维基的“<a href="./getting-started">快速开始</a>”章节来获悉下一步该做的事！</p><h2 id="第四步-配置-luckperms" tabindex="-1">第四步：配置 LuckPerms <a class="header-anchor" href="#第四步-配置-luckperms" aria-label="Permalink to &quot;第四步：配置 LuckPerms&quot;">​</a></h2><p>若要个性化 LuckPerms 的配置，你需要对其的配置文件进行修改。</p><p>返回“文件管理器”，打开 <code>plugins</code>/<code>mods</code> 文件夹或 <code>config</code> 文件夹（对于 Sponge、Fabric 或 Forge 服务端而言）。之后，打开其中的 <code>LuckPerms</code> 文件夹。</p><p><img src="'+d+'" alt=""><br> 在这里你会找到一些文件。其中比较重要的是：</p><ul><li><code>config.yml</code> 或 <code>luckperms.conf</code> - 此为 LuckPerms 的配置文件</li><li><code>luckprems-h2-v2.mv.db</code> - 此为 LuckPerms 用于存储权限数据的数据库文件（勿删！） 你可点击 <code>config.yml</code> 或 <code>luckperms.conf</code> 对其进行浏览或编辑。</li></ul><h2 id="第五步-可选-配置-luckperms-的-mysql-数据库或存储数据的-yml-文件" tabindex="-1">第五步（可选）：配置 LuckPerms 的 MySQL 数据库或存储数据的 .yml 文件 <a class="header-anchor" href="#第五步-可选-配置-luckperms-的-mysql-数据库或存储数据的-yml-文件" aria-label="Permalink to &quot;第五步（可选）：配置 LuckPerms 的 MySQL 数据库或存储数据的 .yml 文件&quot;">​</a></h2><p>默认情况下，LuckPerms 会将数据存储在名为“H2”的文件数据库。这可以在保持效率的同时还能让用户无需额外配置即可开始使用本插件。</p><p>如果你想要 LuckPerms 的数据存储在<strong>可读、可编辑的 .yml 文件中</strong>的话，打开 <code>config.yml</code> 或 <code>luckperms.conf</code>，下拉并找到“存储设置（Storage Settings）”部分并将 <code>storage-method</code> 项设置为 <code>yaml</code>，之后保存并重启服务器。</p><p>若你在一台服务器中运行多个服务端（或是计划在未来这么做），你就需要设置一个诸如 <strong>MySQL</strong> 的远程数据库来存储数据。</p><p>大多数服务器托管商都会免费提供这些！<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup>找到“数据库”菜单，再点击“创建数据库”。若弹出输入窗口，只需选择“MySQL”为数据库类型并输入名称即可。</p><figure><img src="'+k+'" alt="" tabindex="0"><figcaption></figcaption></figure><p>创建数据库后，弹出的窗口会显示数据库域名、名称、用户名及密码。</p><figure><img src="'+h+'" alt="" tabindex="0"><figcaption></figcaption></figure><p>获取这些内容后，记住这些内容（或复制你的表格）并返回文件管理器 LuckPerms 的 <code>config.yml</code>/<code>luckperms.conf</code> 下并将其打开。</p><p>下拉至“存储设定（Storage Settings）” 并将 <code>storage-method</code> 设置为 <code>mysql</code>，然后再在 <code>data:</code> 下将刚才设置的内容填入此处。</p><p><img src="'+g+'" alt=""><br> 点击保存之后，重启你的服务器。</p><p>你可以观察控制台日志来确认 MySQL 数据库是否正确安装。若你在（载入数据提供者... [MYSQL]）<code>Loading storage provider... [MYSQL]</code> 之后没有看见报错信息，说明你已经正确搭建了 MySQL 数据库！</p><p><img src="'+f+'" alt=""><br> 记住，群组服下的每一个子服都需要如此配置连接至同一个数据库（但无需重复安装 MySQL）。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="我应该把-luckperms-装在哪" tabindex="-1">我应该把 LuckPerms 装在哪？ <a class="header-anchor" href="#我应该把-luckperms-装在哪" aria-label="Permalink to &quot;我应该把 LuckPerms 装在哪？&quot;">​</a></h3><ul><li>若你正在运行的是群组服，你需要把 LuckPerms 安装至每个子服。</li><li>若你也想要在 Velocity/BungeeCord 群组上使用 LuckPerms，你应该将 LuckPerms-Velocity.jar 或 LuckPerms-Bungee.jar 放入你的群组核心的插件文件夹。</li><li>若你选择只在群组服核心上安装 LuckPerms，不会对后端的其他子服造成任何影响。若你想要使用这些功能，你应当也在这些子服上安装 LuckPerms。</li></ul><h3 id="我可以只把-luckperms-装在-bungeecord-上吗" tabindex="-1">我可以只把 LuckPerms 装在 BungeeCord 上吗？ <a class="header-anchor" href="#我可以只把-luckperms-装在-bungeecord-上吗" aria-label="Permalink to &quot;我可以只把 LuckPerms 装在 BungeeCord 上吗？&quot;">​</a></h3><ul><li>在 Velocity/Bungeecord 上使用的权限系统完全独立于后端子服。</li><li>你<strong>可以</strong>只将插件装在群组服上，但这会导致由 Bukkit/Sponge 插件或 Fabric/Forge 模组处理的权限检查不会被 LuckPerms 处理。</li></ul><h2 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to &quot;要求&quot;">​</a></h2><p>LuckPerms 对安装环境有一些要求。不过<em>大多数</em>服务器都可以达到这些条件。</p><ul><li>Java 11 或更高版本</li><li>首次载入 LuckPerms 时需要联网</li></ul><h3 id="java-11" tabindex="-1">Java 11 <a class="header-anchor" href="#java-11" aria-label="Permalink to &quot;Java 11&quot;">​</a></h3><p>你的服务器使用的 Java 版本必须不小于 11。LuckPerms 不能在更旧版本的 Java 环境中运行。</p><p>部分核心或新版本可能要求更高的 Java 版本（如 Java 21），LuckPerms 同样支持。</p><h3 id="网络连接" tabindex="-1">网络连接 <a class="header-anchor" href="#网络连接" aria-label="Permalink to &quot;网络连接&quot;">​</a></h3><p>LuckPerms 使用了一系列<a href="./project-info/external-connections">外部库</a>，其中部分内容会在<a href="./project-info/external-connections#下载外部库">运行时自动下载</a>。</p><p>若你的服务器网络不佳或尚未联网，你可以（在有网的地方先）本地安装 LP，然后将 <code>/LuckPerms/libs/</code> 下的文件复制到服务器中。</p><h2 id="兼容性" tabindex="-1">兼容性 <a class="header-anchor" href="#兼容性" aria-label="Permalink to &quot;兼容性&quot;">​</a></h2><p>下面会展示部分已知问题。大部分情况都超出了我们的控制——所以我们无法通过 LuckPerms 本身的代码解决。</p><p>部分已在最新版的插件中修复——不过旧版本仍然存在。</p><h3 id="其他权限插件" tabindex="-1">其他权限插件 <a class="header-anchor" href="#其他权限插件" aria-label="Permalink to &quot;其他权限插件&quot;">​</a></h3><p>若要 LuckPerms 完全运行且处理所有的权限检查，你的服务器中应该只留下它一个权限插件（除非你需要用插件进行数据迁移）！</p><h3 id="低版本-minecraft" tabindex="-1">低版本 Minecraft <a class="header-anchor" href="#低版本-minecraft" aria-label="Permalink to &quot;低版本 Minecraft&quot;">​</a></h3><p>目前 LuckPerms 的发布版与低于 1.8.8 的版本不兼容。</p><p>支持 1.7.10 且面向 Bukkit 的 LuckPerms 可以在我们的<a href="https://luckperms.net/download/" target="_blank" rel="noreferrer">下载页</a>找到。</p>',57)),o(t),o(s),e[1]||(e[1]=r('<hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>可惜的是，国内服务商并不会主动提供这些。若你需要相似的教程，请访问<a href="https://www.runoob.com/mysql/mysql-install.html" target="_blank" rel="noreferrer">Runoob：MySQL安装及搭建教程</a>。 <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',2))])}const C=i(P,[["render",b]]);export{v as __pageData,C as default};
